import{_ as i,c as e,o as r,ag as l}from"./chunks/framework.DfL_BkQ-.js";const d=JSON.parse('{"title":"プライバシーポリシー","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/privacy.md","filePath":"ja/guide/privacy.md","lastUpdated":1794112334000}'),t={name:"ja/guide/privacy.md"};function o(s,a,h,n,c,p){return r(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="プライバシーポリシー" tabindex="-1">プライバシーポリシー <a class="header-anchor" href="#プライバシーポリシー" aria-label="Permalink to &quot;プライバシーポリシー&quot;">​</a></h1><h2 id="データの収集" tabindex="-1">データの収集 <a class="header-anchor" href="#データの収集" aria-label="Permalink to &quot;データの収集&quot;">​</a></h2><p>開発者は本アプリからいかなるデータも収集しません。</p><h3 id="収集しない情報" tabindex="-1">収集しない情報 <a class="header-anchor" href="#収集しない情報" aria-label="Permalink to &quot;収集しない情報&quot;">​</a></h3><ul><li>個人情報</li><li>利用統計</li><li>デバイス情報</li><li>位置情報</li><li>画像の内容やメタデータ</li><li>閲覧履歴</li><li>その他のユーザーデータ</li></ul><h3 id="chrome-拡張機能" tabindex="-1">Chrome 拡張機能 <a class="header-anchor" href="#chrome-拡張機能" aria-label="Permalink to &quot;Chrome 拡張機能&quot;">​</a></h3><p>Nicasa Chrome 拡張機能は、画像閲覧機能のために画像 URL を抽出する目的に限り、ページコンテンツへのアクセスを要求します。この拡張機能は：</p><ul><li>閲覧履歴を読み取ったり保存したりしません</li><li>ユーザーの行動を追跡しません</li><li>外部サーバーにいかなるデータも送信しません</li><li>画像 URL をブラウザ内でローカルに処理するだけです</li></ul><h3 id="ローカル処理" tabindex="-1">ローカル処理 <a class="header-anchor" href="#ローカル処理" aria-label="Permalink to &quot;ローカル処理&quot;">​</a></h3><p>画像の処理、編集、閲覧はすべて端末上で行われます。画像やデータが外部サーバーにアップロードされることはありません。</p><h3 id="権限" tabindex="-1">権限 <a class="header-anchor" href="#権限" aria-label="Permalink to &quot;権限&quot;">​</a></h3><p>Nicasa は macOS で以下の権限を要求します：</p><ul><li><strong>画面収録</strong>：スクリーンショット機能に必要</li><li><strong>アクセシビリティ</strong>：任意、オーバーレイモードの機能に使用</li><li><strong>ファイルとフォルダ</strong>：画像閲覧のためユーザーが選択したディレクトリへのアクセス</li></ul><p>これらの権限は「システム設定 &gt; プライバシーとセキュリティ」で管理できます。</p><h3 id="第三者サービス" tabindex="-1">第三者サービス <a class="header-anchor" href="#第三者サービス" aria-label="Permalink to &quot;第三者サービス&quot;">​</a></h3><p>Nicasa は第三者による分析、広告、データ収集サービスを一切組み込んでいません。</p><h3 id="プライバシーの選択" tabindex="-1">プライバシーの選択 <a class="header-anchor" href="#プライバシーの選択" aria-label="Permalink to &quot;プライバシーの選択&quot;">​</a></h3><p>プライバシーに関する権利（アクセス、削除、ポータビリティ、オプトアウトの各請求など）を行使したい場合、または Nicasa があなたに関する個人データを保有しているとお考えの場合は、以下のいずれかの方法で請求を送信できます：</p><ul><li>メール：nicasa@w3cub.com</li><li>プライバシー issue の作成：<a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">https://github.com/nicasa-app/nicasa-support/issues</a></li><li>公開しているプライバシー選択ページの利用：/ja/guide/privacy-choices</li></ul><p>上述のとおり Nicasa は個人データを収集しないため、多くの請求は「個人データを保有していない」旨の確認をもって回答されます。将来のリリースで個人データの収集を開始した場合は、本ページとプライバシー選択フォームが請求の送信と追跡の手段を提供します。</p><p>正当なプライバシー請求には 30 日以内に回答するよう努めます。</p><h3 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to &quot;更新&quot;">​</a></h3><p>本プライバシーポリシーはアプリの新バージョンに伴い更新される場合があります。重要な変更がある場合はユーザーに通知します。</p><h3 id="お問い合わせ" tabindex="-1">お問い合わせ <a class="header-anchor" href="#お問い合わせ" aria-label="Permalink to &quot;お問い合わせ&quot;">​</a></h3><p>プライバシーに関するご質問は、<a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">GitHub リポジトリ</a>からお問い合わせください。</p>',25)])])}const m=i(t,[["render",o]]);export{d as __pageData,m as default};
